                              <span class="boost-sd__format-currency boost-sd__format-currency--price-sale"><span class="">{{ bundle.totalBundlePrice }}</span></span>
                              <span class="boost-sd__format-currency boost-sd__format-currency--price-compare"><span class="">{{ bundle.totalPrice }}</span></span>
