              position: relative;
              height: 45px;
              margin-bottom: 10px;
            }

            .boost-sd__instant-search-placeholder-item::marker {
              font-size: 0;
            }

            .boost-sd__instant-search-placeholder-item::before {
              content: '';
              position: absolute;
              top: 8px;
              left: 55px;
              display: inline-block;
              width: calc(100% - 55px);
              height: 10px;
              background: -webkit-gradient(linear,
