                      <path fill-rule="evenodd" clip-rule="evenodd" d="M19.3536 5.35355C19.5488 5.15829 19.5488 4.84171 19.3536 4.64645C19.1583 4.45118 18.8417 4.45118 18.6464 4.64645L12 11.2929L5.35355 4.64645C5.15829 4.45118 4.84171 4.45118 4.64645 4.64645C4.45118 4.84171 4.45118 5.15829 4.64645 5.35355L11.2929 12L4.64645 18.6464C4.45118 18.8417 4.45118 19.1583 4.64645 19.3536C4.84171 19.5488 5.15829 19.5488 5.35355 19.3536L12 12.7071L18.6464 19.3536C18.8417 19.5488 19.1583 19.5488 19.3536 19.3536C19.5488 19.1583 19.5488 18.8417 19.3536 18.6464L12.7071 12L19.3536 5.35355Z" fill="#222222"></path>
                    </svg>
                  </button>
                </div>
                {% endif %}
              </div>
              {% if isShowPopupDynamicBundle and bundle and bundle.bundle_display_type == 'bottom' or bundle.bundle_display_type == nil %}
            </div>
            {% endif %}
            {% assign firstBundleRendered = true %}
            {% endif %}
            {% endfor %}
          </div>
          <!-- TEMPLATE VIEW ALL -->
          {% assign productNumber = '0' %}
          {% for item in suggestionBlocksList %}
          {% if item.type == 'products' %}
          {% assign productNumber = item.number %}
          {% endif %}
          {% endfor %}
          {% if products.size > 0 and total_product > productNumber -%}
          {%- assign count = total_product -%}
          {% assign viewAllTranslated = 'suggestion.viewAll' | translate: translations, 'View all {{ count }} products' | replace: '{{ count }}', count -%}
          <div aria-label='Button: {{ viewAllTranslated }}' class='boost-sd__view-all' data-group='view-all-products' data-title='{{ query | escape }}'>
            <a class='boost-sd__view-all-link' href='{{ currentLocale }}/search?q={{ query | url_encode }}'>
              <span class='boost-sd__view-all-text'>
                {{ viewAllTranslated }}
                <svg class='boost-sd__view-all-icon' width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'>
                  <path fill-rule="evenodd" clip-rule="evenodd" d="M14.1657 7.43443L10.1657 3.43443C9.8529 3.12163 9.3473 3.12163 9.0345 3.43443C8.7217 3.74723 8.7217 4.25283 9.0345 4.56563L11.6689 7.20003H2.4001C1.9577 7.20003 1.6001 7.55843 1.6001 8.00003C1.6001 8.44163 1.9577 8.80003 2.4001 8.80003H11.6689L9.0345 11.4344C8.7217 11.7472 8.7217 12.2528 9.0345 12.5656C9.1905 12.7216 9.3953 12.8 9.6001 12.8C9.8049 12.8 10.0097 12.7216 10.1657 12.5656L14.1657 8.56563C14.4785 8.25283 14.4785 7.74723 14.1657 7.43443" fill="#5C5F62"></path>
                </svg>
              </span>
            </a>
          </div>
          {% endif %}
          {% endif %}
        </div>
        {% else %}
        {% assign autocompleteClasses = '' %}
        {% if suggestions.size == 0 and collections.size == 0 and pages.size == 0 -%}
        {% assign autocompleteClasses = autocompleteClasses | append: 'boost-sd__instant-search-no-other ' %}
        {% endif %}
        {% if products.size == 0 -%}
        {% assign autocompleteClasses = autocompleteClasses | append: 'boost-sd__instant-search-no-product ' %}
        {% endif %}
        <div class='boost-sd__instant-search-autocomplete {{ autocompleteClasses }} boost-sd__g-flexColumn'>
          {% if hasSuggestions or hasCollections or hasPages or hasProducts or did_you_mean.size != 0 -%}
          <div class='boost-sd__instant-search-column boost-sd__instant-search-column--others boost-sd__g-scrollable'>
            <!-- TEMPLATE DID YOU MEAN -->
            {% assign termList = '' %}
            {% if did_you_mean.size != 0 and all_empty == false %}
            <div class='boost-sd__spelling-correction' data-group='empty' data-aria-label='{{ query | escape }}' data-label='{{ query | escape }}'>
              <p class='boost-sd__spelling-correction-desc boost-sd__spelling-correction-desc--list'>
                {% for term in did_you_mean %}
                {% assign escapedTerm = term | escape %}
                {% assign termList = termList | append: '<a tabindex="-1" class="boost-sd__spelling-correction-suggest-link" href="/search?q=[[term]]">[[term]]</a>' | replace: '[[term]]', escapedTerm %}
                {% endfor %}
                {% assign didYouMeanTranslated = 'suggestion.didYouMean' | translate: translations, 'Did you mean: {{ terms }}' | replace: '{{ terms }}', termList -%}
                {{ didYouMeanTranslated }}
              </p>
            </div>
            {% endif %}
            <!-- TEMPLATE SUGGESTION QUERIES BLOCKS -->
            <!-- ISW with results -->
            {% assign queriesMobileClasses = '' %}
            {% if suggestionMobileStyle == 'style1' %}
            {% assign queriesMobileClasses = queriesMobileClasses | append: 'boost-sd__suggestion-queries-item--mobile-style1' %}
            {% endif %}
            {% if suggestionMobileStyle == 'style2' %}
            {% assign queriesMobileClasses = queriesMobileClasses | append: 'boost-sd__suggestion-queries-item--mobile-style2' %}
            {% endif %}
            {% if suggestions.size > 0 -%}
            <div class='boost-sd__suggestion-queries-group'>
              <h3 tabindex='0' role='text' class='boost-sd__header-item boost-sd__suggestion-queries-header boost-sd__suggestion-queries-header--suggestions'>
                {{ 'suggestion.instantSearchSuggestionsLabel' | translate: translations, 'Popular suggestions' }}
              </h3>
              <ul aria-label='Suggestion list' class='boost-sd__suggestion-queries-list'>
                {% for suggestion in suggestions limit: 10 %}
                <li class='boost-sd__suggestion-queries-item boost-sd__suggestion-queries-item--suggestion {{ queriesMobileClasses }}' data-extra-param='false' data-title='{{ suggestion | escape }}'>
                  {% assign suggestionHref = '' %}
                  {% if redirects[suggestion] %}
                  {% assign suggestionHref = redirects[suggestion] %}
                  {% else %}
                  {% assign suggestionHref = currentLocale | append: '/search?q=' | append: suggestion %}
                  {% endif %}
                  <a aria-label='Suggestion : {{ suggestion | escape }}' href='{{ suggestionHref | escape }}' class='boost-sd__suggestion-queries-link'>
                    <span aria-hidden='true'>{{ suggestion | escape }}</span>
                  </a>
                </li>
                {% endfor %}
              </ul>
            </div>
            {% endif %}
            {% if contentOrder == 'one-column' %}
            {% if products.size > 0 -%}
            <div class='boost-sd__instant-search-product-list'>
              <h3 class='boost-sd__header-item boost-sd__instant-search-product-list-header'>
                {{ 'suggestion.instantSearchProductsLabel' | translate: translations, 'Products' }}
              </h3>
              <ul aria-label="Product list suggestion" class="boost-sd__instant-search-product-list-items">
                {% assign firstProductRendered = false %}
                {% comment %} Find the newest classic bundle and newest volume bundle by updated_at {% endcomment %}
                {% assign bestClassicBundle = nil %}
                {% assign bestVolumeBundle = nil %}
                {% for bundle in bundles %}
                {% if bundle.bundle_type == 'classic' and bundle.bundle_display_type == 'product' %}
                {% if bestClassicBundle == nil or bundle.updated_at > bestClassicBundle.updated_at %}
                {% assign bestClassicBundle = bundle %}
                {% endif %}
                {% endif %}
                {% if bundle.bundle_type == 'volume' %}
                {% if bestVolumeBundle == nil or bundle.updated_at > bestVolumeBundle.updated_at %}
                {% assign bestVolumeBundle = bundle %}
                {% endif %}
                {% endif %}
                {% endfor %}
                {% comment %} Render the bundle placeholder with the highest updated_at {% endcomment %}
                {% if bestClassicBundle != nil or bestVolumeBundle != nil %}
                {% if bestVolumeBundle == nil or bestClassicBundle.updated_at >= bestVolumeBundle.updated_at %}
                {% assign showEmbedded = true %}
                {% else %}
                {% assign showEmbedded = false %}
                {% endif %}
                {% if showEmbedded %}
                {% assign bundle = bestClassicBundle %}
                {% assign widgetDesignSettings = widgetDesignSettingsMap[bundle.widgetId] %}
                {% assign embeddedIsw = true %}
                <li aria-label="Embedded Bundle: {{ widgetDesignSettings.titleName | escape }}. Click here to show popup!" aria-selected="false" class="boost-sd__suggestion-queries-item boost-sd__suggestion-queries-item--product boost-sd__suggestion-queries-item--embedded-bundle" data-title="{{ widgetDesignSettings.titleName | escape }}">
                  <!-- TEMPLATE RECOMMENDATION EMBEDDED BUNDLE -->
                  {% assign isSale = false -%}
                  {% if bundle.discount_type == 'percent' or bundle.discount_type == 'net' and bundle.discount_value > 0 %}
                  {% assign isSale = true -%}
                  {% endif -%}
                  {% if embeddedIsw %}
                  {% assign imagesClasses = " boost-sd__suggestion-queries-item-product boost-sd__suggestion-queries-item-product--left" %}
                  {% assign infoClasses = " boost-sd__suggestion-queries-item-product boost-sd__suggestion-queries-item-product--right" %}
                  {% assign titleClasses = "boost-sd__suggestion-queries-item-title" %}
                  {% assign priceClasses = "boost-sd__suggestion-queries-item-price" %}
                  {% else %}
                  {% assign titleClasses = "boost-sd__product-title" %}
                  {% assign priceClasses = "boost-sd__product-price" %}
                  {% endif %}
                  <div role="link" tabindex="0" aria-labelledby="bundle-title bundle-price" aria-live="polite" class="boost-sd__product-bundle" data-is-popup-opening='{{ isPopupPredictiveBundleOpening }}' data-widget-id='{{ bundle.widgetId }}' data-product-price='true'>
                    <!-- Display Bundle Image -->
                    <div class="boost-sd__product-bundle-images{{ imagesClasses }}">
                      {%- capture aspectRatioSetting %}portrait{% endcapture -%}
                      {% assign aspectRatio = '' -%}
                      {% if aspectRatioSetting == 'natural' -%}
                      {% for product in bundle.products %}
                      {% assign imageWidth = product.images_info[0].width -%}
                      {% assign imageHeight = product.images_info[0].height -%}
                      {% endfor %}
                      {% assign aspectRatio = aspectRatio | append: 'aspect-ratio: ' | append: imageWidth | append: '/' | append: imageHeight -%}
                      {% endif -%}
                      <!-- Display Mixed Product Images if selected -->
                      {% if widgetDesignSettings.bundleImageType == 'combo' %}
                      <div class="boost-sd__product-image-wrapper boost-sd__product-image-wrapper--{{ bundle.products.size }} boost-sd__product-image-wrapper--portrait" style="{{ aspectRatio }}">
                        {% for product in bundle.products %}
                        <div class="boost-sd__product-image">
                          {% if product.images_info[0] %}
                          <img id="product-image-{{ product.id }}" class="boost-sd__product-image-img boost-sd__product-image-img--main boost-sd__product-image-img--autoheight" src="{{ product.images_info[0].src }}" alt="{{ product.title | escape }}" width="auto" height="auto" />
                          {% else %}
                          <img id="product-image-{{ product.id }}" class="boost-sd__product-image-img boost-sd__product-image-img--autoheight" src="https://cdn.shopify.com/extensions/201f4d7b-8d39-43a4-82de-e6f412341695/0.0.0/assets/boost-pfs-no-image.jpg?v=1677838268" alt="No image" width="auto" height="auto" />
                          {% endif %}
                        </div>
                        {% endfor %}
                      </div>
                      {% elsif widgetDesignSettings.bundleImageType == 'upload' %}
                      <!-- Use the newly uploaded image -->
                      <div class="boost-sd__product-image-wrapper boost-sd__product-image-wrapper--full-box boost-sd__product-image-wrapper--portrait" style="{{ aspectRatio }}">
                        <div class="boost-sd__product-image">
                          <img class="boost-sd__product-image-img boost-sd__product-image-img--fullheight" src="{{ widgetDesignSettings.bundleImageLink | image_url: 'large' }}" alt="{{ widgetDesignSettings.bundleImageData.title | escape }}" width="auto" height="auto" />
                        </div>
                      </div>
                      {% else %}
                      <!-- Use Single Product Images: bundleImageType === 'single' -->
                      <div class="boost-sd__product-image-wrapper boost-sd__product-image-wrapper--full-box boost-sd__product-image-wrapper--portrait" style="{{ aspectRatio }}">
                        {% for product in bundle.products %}
                        {% if widgetDesignSettings.bundleImageData == product.id %}
                        <div class="boost-sd__product-image">
                          {% if product.images_info[0] %}
                          <img id="product-image-{{ widgetDesignSettings.bundleImageData }}" class="boost-sd__product-image-img boost-sd__product-image-img--main boost-sd__product-image-img--fullheight" src="{{ product.images_info[0].src }}" alt="{{ product.title | escape }}" width="auto" height="auto" />
                          {% else %}
                          <img id="product-image-{{ widgetDesignSettings.bundleImageData }}" class="boost-sd__product-image-img boost-sd__product-image-img--fullheight" src="https://cdn.shopify.com/extensions/201f4d7b-8d39-43a4-82de-e6f412341695/0.0.0/assets/boost-pfs-no-image.jpg?v=1677838268" alt="No image" width="auto" height="auto" />
                          {% endif %}
                        </div>
                        {% endif %}
                        {% endfor %}
                      </div>
                      {% endif %}
                    </div>
                    <!-- Display Bundle Information -->
                    <div class="boost-sd__product-bundle-info{{ infoClasses }}">
                      <div class="boost-sd__product-bundle-info-wrapper boost-sd__product-info boost-sd__product-info--left">
                        {% assign widgetNameTranslationLabel = 'recommendation.' | append: bundle.widgetId %}
                        <div id="bundle-title" class="{{ titleClasses }}">
                          {{ widgetNameTranslationLabel | translate: translations, widgetDesignSettings.titleName }}
                        </div>
                        <div id="bundle-price" class="{{ priceClasses }}">
                          {% if embeddedIsw %}
                          {% if isSale %}
                          <span class="boost-sd__suggestion-queries-item-amount boost-sd__suggestion-queries-item-amount--sale">
                            <span class="boost-sd__format-currency boost-sd__format-currency--price-sale"><span class="">{{ bundle.totalBundlePrice }}</span></span>
                            <span class="boost-sd__format-currency boost-sd__format-currency--price-compare"><span class="">{{ bundle.totalPrice }}</span></span>
                          </span>
                          {% else %}
                          <span class="boost-sd__suggestion-queries-item-amount boost-sd__suggestion-queries-item-amount--regular">
                            <span class="boost-sd__format-currency"><span class="">{{ bundle.totalPrice }}</span></span>
                          </span>
                          {% endif %}
                          {% else %}
                          {% assign priceValueWithFormat = bundle.totalBundlePrice %}
                          {% assign compareAtPriceWithFormat = bundle.totalPrice %}
                          <!-- Price compare display left or right -->
                          <div class="boost-sd__product-price-wrapper">
                            <span class="boost-sd__product-price-content   boost-sd__product-price-content--text-align-left">
                              <span role="text" aria-label="Sale price: {{ priceValueWithFormat }}" class="{% if isSale == true %}boost-sd__product-price--sale{% else %}boost-sd__product-price--default{% endif %}">
                                <span class="boost-sd__format-currency">{{ priceValueWithFormat }}</span>
                              </span>
                              {% if compareAtPriceWithFormat != '' -%}
                              <span role="text" aria-label="Regular price: {{ compareAtPriceWithFormat }}" class="boost-sd__format-currency boost-sd__format-currency--price-compare boost-sd__product-price--compare"> {{ compareAtPriceWithFormat }}
                              </span>
                              {% endif -%}
                            </span>
                          </div>
                          {% endif %}
                        </div>
                      </div>
                    </div>
                  </div>
                </li>
                {% else %}
                {% assign bundle = bestVolumeBundle %}
                {% assign widgetDesignSettings = widgetDesignSettingsMap[bundle.widgetId] %}
                {% assign volumeIsw = true %}
                <li aria-label="Volume Bundle: {{ widgetDesignSettings.titleName | escape }}. Click here to show popup!" aria-selected="false" data-title="{{ widgetDesignSettings.titleName | escape }}" class="boost-sd__suggestion-queries-item boost-sd__suggestion-queries-item--product boost-sd__suggestion-queries-item--volume-bundle">
                  <!-- TEMPLATE RECOMMENDATION VOLUME BUNDLE PRODUCT -->
                  {%- capture aspectRatio %}portrait{% endcapture -%}
                  {% assign product = bundle.matchedProduct -%}
                  {% assign aspectRatio = '' -%}
                  {% if aspectRatio == 'natural' -%}
                  {% assign imageWidth = product.images_info[0].width -%}
                  {% assign imageHeight = product.images_info[0].height -%}
                  {% assign aspectRatio = aspectRatio | append: 'aspect-ratio:' | append: imageWidth | append: '/' | append: imageHeight -%}
                  {% endif -%}
                  {% if volumeIsw == true %}
                  {% assign imagesClasses = " boost-sd__suggestion-queries-item-product boost-sd__suggestion-queries-item-product--left" %}
                  {% assign infoClasses = " boost-sd__suggestion-queries-item-product boost-sd__suggestion-queries-item-product--right" %}
                  {% assign titleClasses = " boost-sd__suggestion-queries-item-title" %}
                  {% assign priceClasses = " boost-sd__suggestion-queries-item-price" %}
                  {% else %}
                  {% assign titleClasses = " boost-sd__product-title" %}
                  {% assign priceClasses = " boost-sd__product-price" %}
                  {% endif %}
                  {% assign widgetNameTranslationLabel = 'recommendation.' | append: bundle.widgetId %}
                  <div role="link" tabindex="0" aria-labelledby="bundle-title bundle-label bundle-price" aria-live="polite" class="boost-sd__volume-bundle-product-item" data-is-popup-opening='{{ isPopupVolumeBundleOpening }}' data-widget-id='{{ bundle.widgetId }}' data-product-price='true' data-product-id="{{ product.id }}">
                    <div class="boost-sd__volume-bundle-product-card{{ imagesClasses }}">
                      {% if widgetDesignSettings.bundleImageType == 'upload' %}
                      <div class="boost-sd__product-image-wrapper boost-sd__product-image-wrapper--full-box boost-sd__product-image-wrapper--portrait" style="{{ aspectRatio }}">
                        <figure class="boost-sd__product-image boost-sd__volume-bundle-product-image">
                          <img class="boost-sd__product-image-img boost-sd__product-image-img--fullheight boost-sd__volume-bundle-product-img" src="{{ widgetDesignSettings.bundleImageLink | image_url: 'large' }}" alt="{{ widgetDesignSettings.bundleImageData.title | escape }}" width="auto" height="auto" />
                        </figure>
                      </div>
                      {% elsif widgetDesignSettings.bundleImageType == 'single' %}
                      <div class="boost-sd__product-image-wrapper boost-sd__product-image-wrapper--full-box boost-sd__product-image-wrapper--portrait" style="{{ aspectRatio }}">
                        <div class="boost-sd__product-image boost-sd__volume-bundle-product-image">
                          {% if product.images_info[0] %}
                          <img id="product-image-{{ widgetDesignSettings.bundleImageData }}" class="boost-sd__product-image-img boost-sd__product-image-img--main boost-sd__product-image-img--fullheight boost-sd__volume-bundle-product-img" src="{{ product.images_info[0].src }}" alt="{{ product.title | escape }}" width="auto" height="auto" />
                          {% endif %}
                        </div>
                      </div>
                      {% else %}
                      <figure class="boost-sd__product-image boost-sd__volume-bundle-product-image">
                        <img id="product-image-{{ product.id }}" class="boost-sd__product-image-img boost-sd__product-image-img--autoheight" src="https://cdn.shopify.com/extensions/201f4d7b-8d39-43a4-82de-e6f412341695/0.0.0/assets/boost-pfs-no-image.jpg?v=1677838268" alt="No image" width="auto" height="auto" />
                      </figure>
                      {% endif %}
                    </div>
                    <figcaption class="boost-sd__volume-bundle-product-info{{ infoClasses }}">
                      <div class="boost-sd__product-bundle-info-wrapper boost-sd__product-info boost-sd__product-info--left">
                        <div id="bundle-title" class="boost-sd__volume-bundle-product-title{{ titleClasses }}">
                          {{ widgetNameTranslationLabel | translate: translations, widgetDesignSettings.titleName }}
                        </div>
                        <p id="bundle-price" class="boost-sd__volume-bundle-product-price{{ priceClasses }}">
                          <span class="boost-sd__volume-bundle-product-single">
                            1 for <span>{{ bundle.productMinPrice }}</span>
                          </span>
                          <br>
                          <span class="boost-sd__volume-bundle-product-combo">
                            {{ bundle.bundleOptions[0].items }} for <span class="boost-sd__volume-bundle-product-discount">
                              {% if volumeIsw %}
                              <span class="boost-sd__suggestion-queries-item-amount">
                                <span class="boost-sd__format-currency boost-sd__format-currency--price-sale">{{ bundle.bundleOptions[0].discountedPrice }}</span>
                              </span>
                              {% else %}
                              <span class="boost-sd__product-price-content">
                                <span role="text" aria-label="Sale price: {{ bundle.bundleOptions[0].discountedPrice }}" class="boost-sd__product-price--sale">
                                  {{ bundle.bundleOptions[0].discountedPrice }}
                                </span>
                                <span role="text" aria-label="Regular price: {{ bundle.bundleOptions[0].originalPrice }}" class="boost-sd__format-currency boost-sd__format-currency--price-compare">{{ bundle.bundleOptions[0].originalPrice }}</span>
                              </span>
                              {% endif %}
                            </span>
                          </span>
                        </p>
                      </div>
                    </figcaption>
                  </div>
                </li>
                {% endif %}
                {% assign firstProductRendered = true %}
                {% endif %}
                {% for product in products limit: 10 %}
                <li class="boost-sd__suggestion-queries-item boost-sd__suggestion-queries-item--product" data-id="{{ product.id | escape }}" data-title="{{ product.title | escape }}">
                  <a href="{{ currentLocale }}/products/{{ product.handle | escape }}" class="boost-sd__suggestion-queries-item-link" target="_parent" rel="noreferrer">
                    <div class="boost-sd__suggestion-queries-item-product boost-sd__suggestion-queries-item-product--left">
                      {% if product.available != true %}
                      <div class="boost-sd__suggestion-queries-item-badge boost-sd__suggestion-queries-item-badge--sold-out">{{ "productItem.productItemSoldOut" | translate: translations, "Sold out" }}</div>
                      {% endif %}
                      {% if product.available == true and product.percent_sale_min and product.percent_sale_min > 0 %}
                      {% assign compareAtPriceMin = product.compare_at_price_min | default: 0 %}
                      {% if compareAtPriceMin > product.price_min %}
                      {% assign percent = compareAtPriceMin | minus: product.price_min | times: 100 | divided_by: compareAtPriceMin | round %}
                      {% assign salePercent = percent | append: '%' %}
                      {% assign saleAmount = product.sale_amount_format %}
                      <div class="boost-sd__suggestion-queries-item-badge boost-sd__suggestion-queries-item-badge--sale">
                        {% assign textProductItemSaleTranslated = "productItem.productItemSale" | translate: translations, "Sale" | replace: '{{salePercent}}', salePercent | replace: '{{saleAmount}}', saleAmount -%}
                        <span>{{ textProductItemSaleTranslated }}</span>
                      </div>
                      {% endif %}
                      {% endif %}
                      {% if product.images_info[0] %}
                      {% assign imageSrc = product.images_info[0].src -%}
                      {% assign imagAlt = product.images_info[0].alt -%}
                      {% else %}
                      {% assign imageSrc = "https://cdn.shopify.com/extensions/201f4d7b-8d39-43a4-82de-e6f412341695/0.0.0/assets/boost-pfs-no-image.jpg?v=1677838268" -%}
                      {% assign imagAlt = product.title | escape -%}
                      {% endif %}
                      {% assign widthParam = "&width=" -%}
                      {% assign widths = "400,500,800" | split: "," -%}
                      {% capture srcset -%}
                      {% for width in widths -%}
                      {{ imageSrc }}{{ widthParam }}{{ width }} {{ width }}w,
                      {% endfor -%}
                      {% endcapture -%}
                      <img aria-hidden="true" class="boost-sd__suggestion-queries-item-img" src="{{ imageSrc }}&amp;width=100" alt="{{ imagAlt }}" srcset="{{ srcset }}" sizes="(min-width: 991px) 72px, 50vw" width="auto" height="auto" />
                    </div>
                    <div class="boost-sd__suggestion-queries-item-product boost-sd__suggestion-queries-item-product--right">
                      <p aria-label="Title of product is: {{ product.title | escape }}" class="boost-sd__suggestion-queries-item-title">{{ product.title | escape }}</p>
                      <p class="boost-sd__suggestion-queries-item-price">
                        {% if product.compare_at_price_min != null and product.compare_at_price_min > product.price_min %}
                        <span class="boost-sd__suggestion-queries-item-amount boost-sd__suggestion-queries-item-amount--sale">
                          <span class="boost-sd__format-currency boost-sd__format-currency--price-sale">
                            <span aria-label="Sale price: {{ product.price_min_format }}">{{ product.price_min_format }}</span>
                          </span>
                          <span class="boost-sd__format-currency boost-sd__format-currency--price-compare">
                            <span aria-label="Compare price: {{ product.compare_at_price_min_format }}">{{ product.compare_at_price_min_format }}</span>
                          </span>
                        </span>
                        {% else %}
                        <span class="boost-sd__suggestion-queries-item-amount boost-sd__suggestion-queries-item-amount--regular">
                          <span class="boost-sd__format-currency">
                            <span aria-label="Regular price: {{ product.price_min_format }}">{{ product.price_min_format }}</span>
                          </span>
                        </span>
                        {% endif %}
                      </p>
                      <!--  PRODUCT RATING -->
                      {% assign okendoSnippet = product | product_metafield: 'okendo.ProductListingSnippet' %}
