                          <span>
                            {% if bundle.totalBundlePrice and bundle.rawTotalBundlePrice < bundle.rawTotalPrice %}
                            <span class="boost-sd__recommendation-bundle-total-number">{{ bundle.totalBundlePrice }}</span>
                            {% endif %}
                            {% assign bundleTotalClasses = '' %}
                            {% if bundle.rawTotalPrice > bundle.rawTotalBundlePrice %}
                            {% assign bundleTotalClasses = bundleTotalClasses | append: ' boost-sd__recommendation-bundle-total-number--origin' -%}
                            {% endif %}
                            <span class="boost-sd__recommendation-bundle-total-number{{ bundleTotalClasses }}">{{ bundle.totalPrice }}</span>
                          </span>
                        </div>
                      </div>
                      {% endif %}
                      <button type="button" {% if hasSelectedProduct == false %}disabled{% endif %} aria-label="Add bundle to cart" class="boost-sd__button boost-sd__button--capsule boost-sd__button--add-to-cart boost-sd__recommendation-bundle-button boost-sd__btn-add-to-cart {% if isShowPopupDynamicBundle %}boost-sd__recommendation-dynamic-show-popup{% endif %}" style='color: {{ widgetDesignSettings.buttonTextColor }};
      background-color: {{ widgetDesignSettings.buttonBackgroundColor }};
      font-weight: 500;'>
                        <span>{{ widgetDesignSettings.buttonText }}</span>
                      </button>
                    </div>
                  </div>
                  {% if bundle.isPopupPredictiveBundleOpening == true %}
                  <div class="boost-sd__recommendation-bundle-buttons">
                    <button type="button" aria-label="Close bundle popup" class="boost-sd__button boost-sd__button--back boost-sd__modal-close-btn--dynamic-bundle">
                      <svg xmlns="http://www.w3.org/2000/svg" width="7" height="12" viewBox="0 0 7 12" fill="none">
                        <path d="M6.58942 0.610713C6.26398 0.285274 5.73635 0.285274 5.41091 0.610713L0.611415 5.41021C0.455135 5.56649 0.366829 5.77895 0.366829 5.99996C0.366829 6.22098 0.454629 6.43294 0.610909 6.58922L5.41091 11.3892C5.73635 11.7147 6.26398 11.7147 6.58942 11.3892C6.91486 11.0638 6.91486 10.5362 6.58942 10.2107L2.37867 5.99996L6.58942 1.78922C6.91486 1.46379 6.91486 0.936153 6.58942 0.610713Z" fill="#222222"></path>
                      </svg>
                    </button>
                    <button type="button" aria-label='{{ "close" | translate: translations, "Close" }}' class="boost-sd__button boost-sd__button--transparent boost-sd__button--float boost-sd__modal-close-btn boost-sd__modal-close-btn--dynamic-bundle">
                      <svg class="boost-sd__modal-close-svg" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path fill-rule="evenodd" clip-rule="evenodd" d="M19.3536 5.35355C19.5488 5.15829 19.5488 4.84171 19.3536 4.64645C19.1583 4.45118 18.8417 4.45118 18.6464 4.64645L12 11.2929L5.35355 4.64645C5.15829 4.45118 4.84171 4.45118 4.64645 4.64645C4.45118 4.84171 4.45118 5.15829 4.64645 5.35355L11.2929 12L4.64645 18.6464C4.45118 18.8417 4.45118 19.1583 4.64645 19.3536C4.84171 19.5488 5.15829 19.5488 5.35355 19.3536L12 12.7071L18.6464 19.3536C18.8417 19.5488 19.1583 19.5488 19.3536 19.3536C19.5488 19.1583 19.5488 18.8417 19.3536 18.6464L12.7071 12L19.3536 5.35355Z" fill="#222222"></path>
                      </svg>
                    </button>
                  </div>
                  {% endif %}
                </div>
                {% if isShowPopupDynamicBundle and bundle and bundle.bundle_display_type == 'bottom' or bundle.bundle_display_type == nil %}
              </div>
              {% endif %}
              {% assign firstBundleRendered = true %}
              {% endif %}
              {% endfor %}
            </div>
            <!-- TEMPLATE VIEW ALL -->
            {% assign productNumber = '0' %}
            {% for item in suggestionBlocksList %}
            {% if item.type == 'products' %}
            {% assign productNumber = item.number %}
            {% endif %}
            {% endfor %}
            {% if products.size > 0 and total_product > productNumber -%}
            {%- assign count = total_product -%}
            {% assign viewAllTranslated = 'suggestion.viewAll' | translate: translations, 'View all {{ count }} products' | replace: '{{ count }}', count -%}
            <div aria-label='Button: {{ viewAllTranslated }}' class='boost-sd__view-all' data-group='view-all-products' data-title='{{ query | escape }}'>
              <a class='boost-sd__view-all-link' href='{{ currentLocale }}/search?q={{ query | url_encode }}'>
                <span class='boost-sd__view-all-text'>
                  {{ viewAllTranslated }}
                  <svg class='boost-sd__view-all-icon' width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'>
                    <path fill-rule="evenodd" clip-rule="evenodd" d="M14.1657 7.43443L10.1657 3.43443C9.8529 3.12163 9.3473 3.12163 9.0345 3.43443C8.7217 3.74723 8.7217 4.25283 9.0345 4.56563L11.6689 7.20003H2.4001C1.9577 7.20003 1.6001 7.55843 1.6001 8.00003C1.6001 8.44163 1.9577 8.80003 2.4001 8.80003H11.6689L9.0345 11.4344C8.7217 11.7472 8.7217 12.2528 9.0345 12.5656C9.1905 12.7216 9.3953 12.8 9.6001 12.8C9.8049 12.8 10.0097 12.7216 10.1657 12.5656L14.1657 8.56563C14.4785 8.25283 14.4785 7.74723 14.1657 7.43443" fill="#5C5F62"></path>
                  </svg>
                </span>
              </a>
            </div>
            {% endif %}
          </div>
          {% endif %}
        </div>
        {% endif %}
        {% endif %}
        {% endif %}
      </div>
    </div>
  </div>
</div>"}
